import{_ as a,o as e,c as t,a3 as o}from"./chunks/framework.DdpBa4_E.js";const m=JSON.parse('{"title":"本书的赞誉","description":"","frontmatter":{},"headers":[],"relativePath":"books/bei-taoyan-de-yongqi/03-本书的赞誉.md","filePath":"books/bei-taoyan-de-yongqi/03-本书的赞誉.md","lastUpdated":1794748679000}'),_={name:"books/bei-taoyan-de-yongqi/03-本书的赞誉.md"};function n(r,p,s,i,d,c){return e(),t("div",null,[...p[0]||(p[0]=[o('<h1 id="本书的赞誉" tabindex="-1">本书的赞誉 <a class="header-anchor" href="#本书的赞誉" aria-label="Permalink to &quot;本书的赞誉&quot;">​</a></h1><p>它期许我这一年能拥有被讨厌的勇气，继续大胆地许下做自己的愿望，并勇敢实现它！</p><p>——曾宝仪</p><p>小心检视，你的成功是否只是以害怕被他人讨厌而换来的。若是如此，那你的成功不幸只代表“你为他人活了一辈子”。</p><p>——陈文茜</p><p>一部振奋人心又好读易懂的心灵作品。看完之后，你绝对可以为你无意义的人生增添美丽色彩的意义。好书！</p><p>——身心灵作家　张德芬</p><p>如果说自卑是人类与世界互动的必然结果，那么勇气就是人们在追寻意义人生中的必然能力。它就藏在每个生命体的某个角落，期待着特别的机遇。作者以超越心理咨询的方式，进行心灵的对话，是一本自我成长和疗愈很有帮助的书。</p><p>——心丝带心理志愿者协会会长　国家心理督导师　韦志中</p><p>本书的名字《被讨厌的勇气》，承担这种自由和责任，需要无畏的勇气。这种勇气，是阿德勒心理学的关键词，也是我们人生问题的最终解药。</p><p>——知乎专栏作家　动机在杭州</p><p>这本书绝对不是心灵鸡汤，而是稍带苦涩，但又可治病的良药。也许阅读过程中你会被作者的“犀利”颠覆三观，心生不爽。但不爽过后，抬头看窗外，满目清凉，世界会美好很多……</p><p>——关系心理学家　著名心理咨询师　胡慎之</p><p>这是一本深入浅出的好书，既适合作为大众的自助手册，也可以作为专业人员的临床指南。</p><p>——资深心理咨询师　香港精神分析学会副主席　张沛超</p><p>不死不生。对于一个渴望摆脱旧日模式、重新生出一个自己的人来说，勇气总是第一位的。这个勇气包括不怕试错、不怕被黑、被死千回还能重新活过来的力量。</p><p>——《心探索》杂志执行主编　赵晓梅</p><p>这是一剂烈性药，它会刺痛你的意识的神经。不要抗拒它，一口一口地喝下去。在被你所讨厌的勇气当中，你会重新理解自己的生活方式。</p><p>——壹心理创始人　黄伟强</p><p>成长意味着独立，青年在面对独立的人生之时，以往的各种存在焦虑会涌现而出。本书是人生路上思想的灯塔，它坚定而让人愉悦的言语，是青年未知世界的一点火种，照亮并引导我们属于自己的未来。</p><p>——心理学空间</p>',21)])])}const f=a(_,[["render",n]]);export{m as __pageData,f as default};
